import logging
from taf.internal.managedobject import ManagedObject
from taf.internal.portforwarding.exceptions import ProcessNotExisted


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Netcat(ManagedObject):

    def __init__(self,
                 local_port,
                 remote_host,
                 remote_port,
                 nc_listen_template=None,
                 nc_connect_template=None,
                 **kwargs):
        super(Netcat, self).__init__(**kwargs)

        self._local_port = local_port
        self._remote_host = remote_host
        self._remote_port = remote_port

        self._executor = None

        self._nc_listen_template = nc_listen_template if nc_listen_template else "nc -l -k {local_host} {local_port}"
        self._nc_connect_template = nc_connect_template if nc_connect_template else "nc {remote_host} {remote_port}"

        self._stdin = None
        self._stdout = None
        self._stderr = None

    def attach_executor(self, executor):
        self._executor = executor

    def get_nc_listen_command(self):
        return self._nc_listen_template.format(
            local_host=self._executor.ssh_connection.host,
            local_port=self._local_port)

    def get_nc_connect_command(self):
        return self._nc_connect_template.format(
            remote_host=self._remote_host,
            remote_port=self._remote_port)

    def get_backpipe(self):
        return "/tmp/backpipe_{local_host}_{local_port}_{remote_host}_{remote_port}".format(
            local_host=self._executor.ssh_connection.host,
            local_port=self._local_port,
            remote_host=self._remote_host,
            remote_port=self._remote_port)

    def _setup(self):
        self._executor.execute(
            command="rm -f '{backpipe}' ; mkfifo '{backpipe}'".format(
                backpipe=self.get_backpipe()))
        self._stdin, self._stdout, self._stderr = self._executor.start(
            command=(
                "{nc_listen_command} < '{backpipe}' | "
                "{nc_connect_command} > '{backpipe}'").format(
                    nc_listen_command=self.get_nc_listen_command(),
                    nc_connect_command=self.get_nc_connect_command(),
                    backpipe=self.get_backpipe()),
            use_tty=True)

        if not (self._is_nc_process_existed(self.get_nc_listen_command())
                and self._is_nc_process_existed(self.get_nc_connect_command())):
            raise ProcessNotExisted

    def _is_nc_process_existed(self, command):
        output = self._executor.execute('ps -ef | egrep -c "{}"'.format(command)).strip()
        if not output:
            return False
        return int(output) != 0

    def _teardown(self):
        if not self._stdin.channel.exit_status_ready():
            self._stdin.write("\x03")
            self._stdin.flush()
        exit_status = self._stdin.channel.recv_exit_status()
        logger.debug("exit_status=%r" % exit_status)


class NetcatForwarding(Netcat):
    pass


class NetcatReverseForwarding(Netcat):
    pass
